-- Company stamp printed at the bottom of the invoice paper (the design from the original project).
ALTER TABLE store_invoice_settings ADD COLUMN seal MEDIUMTEXT NULL AFTER logo;

-- Stamps for DEXEL and ARTXEL in the style of the original invoice seals (emblem, wordmark, tagline from each website).
UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.seal = 'data:image/svg+xml;base64,'
WHERE s.name = 'DEXEL' AND t.seal IS NULL;

UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.seal = 'data:image/svg+xml;base64,'
WHERE s.name = 'ARTXEL' AND t.seal IS NULL;

-- The invoice paper is English: use the English company name and address where the seed values are still unchanged.
UPDATE store_invoice_settings t JOIN stores s ON s.id = t.store_id
SET t.legal_name = 'DEXEL', t.address = 'Riyadh, Saudi Arabia'
WHERE s.name = 'DEXEL' AND t.legal_name = 'ديكسل — DEXEL' AND t.address = 'الرياض، المملكة العربية السعودية';
